  AvgVideoCaption_149926_Content_87 = {Text = "왠지"},
  AvgVideoCaption_149926_Content_88 = {
    Text = "나는 누구지?"
  },
  AvgVideoCaption_149926_Content_89 = {
    Text = "나는 진짜 나인 걸까?"
  },
  AvgVideoCaption_149926_Content_9 = {
    Text = "어릴 때부터 아무한테도 사랑받는 일 따윈 없었어."
